from pathlib import Path
import json,html,hashlib
from datetime import datetime,timezone,timedelta
R=Path('/mnt/nvme1/drh/D_VLA');O=R/'experiments/contact_preference/stage012_v1'
s=json.loads((O/'stage2_audit.json').read_text());g=s['grasp_reuse'];loc=s['cross_task_localization']
def esc(v):return html.escape(str(v))
def img(rel):return '<a href="'+esc(rel.split('docs/',1)[1])+'" target="_blank"><img src="'+esc(rel.split('docs/',1)[1])+'" loading="lazy"></a>'
cards=[]
for x in g:
 cards.append('<section class="card"><div class="top"><span class="tag ok">已锁定来源复用</span><h2>'+esc(x['title'])+'</h2></div><p>夹持前帧 '+str(x['query_frame'])+'：绿色为自动稳定表面候选 '+str(x['positive_query_surface_points'])+' 个真实当前 RGB-D 点；持物帧 '+str(x['held_frame'])+'：橙色为实际深度在有限夹指范围内的来源像素。两侧只是同一事件的证据，不是两次抓取，也不是真实接触面积。</p>'+img(x['image'])+'</section>')
d=loc['drawer_demo_0'];f=d['local_fit']
cards.append('<section class="card"><div class="top"><span class="tag partial">局部通过，整段未通过</span><h2>拉开抽屉：遮挡前把手前缘 → 第 70 帧</h2></div><p>左图橙色来自第 0 帧真实深度的局部表面；右图绿色是用局部运动拟合后投到第 70 帧的位置。6 个拟合内点未使用 2 个留出轨迹；留出误差 '+', '.join(f'{v:.2f}' for v in f['70']['heldout_near_errors_mm'])+' mm。第 88 帧还有 1 个留出点误差 8.91 mm，因此不能将第 70 帧的定位延伸为整段可靠接触面。</p>'+img(f['70']['image'])+'</section>')
cards.append('<section class="card"><div class="top"><span class="tag unknown">遮挡面未知</span><h2>转动炉灶开关：旋转时缺少身份锚点</h2></div><p>第 0 帧橙色是从真实深度取出的开关局部表面。第 86 帧夹爪遮住目标区域；原有轨迹在这片表面只有 '+str(loc['stove_demo_0']['visible_valid_tracked_knob_points_at_reference'])+' 个可见有效点，不能验证遮挡面的刚体位置或面积。右图故意不画虚构的接触面。</p>'+img(loc['stove_demo_0']['image'])+'</section>')
cards.append('<section class="card"><div class="top"><span class="tag unknown">对象身份未通过</span><h2>同视频操作两个物体：不能用一整块宽前景代替对象</h2></div><p>这个视频确实同时包含多物体操作，但旧 CF017 初始前景把其它物体与背景纳入同一候选；近手区域并不能自动证明是哪一物体的表面。这里只显示第 300 帧的局部来源诊断，暂不生成两物体的接触面结论。</p>'+img(loc['two_objects_demo_0']['image'])+'</section>')
stamp=datetime.now(timezone(timedelta(hours=8))).isoformat(timespec='seconds')
style='''body{margin:0;background:#0d1421;color:#e9f1fa;font:16px system-ui,"Noto Sans CJK SC",sans-serif;line-height:1.55}main{max-width:1160px;margin:auto;padding:32px 24px 80px}h1{font-size:2rem;margin:.2rem 0}h2{font-size:1.35rem;margin:.2rem 0}p{color:#c9d7e7}.lead{font-size:1.1rem;max-width:1000px}.bar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0 30px}.pill{background:#18263b;border:1px solid #2b4768;border-radius:999px;padding:8px 14px}.card{background:#142338;border:1px solid #2b435f;border-radius:18px;padding:20px;margin:22px 0;box-shadow:0 8px 32px #0003}.top{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.tag{border-radius:99px;padding:4px 10px;font-size:.82rem;font-weight:700}.ok{background:#154b39;color:#a8ffd3}.partial{background:#5c431c;color:#ffe0a0}.unknown{background:#3e3449;color:#e9cff9}img{width:100%;height:auto;border-radius:10px;background:#070c15;display:block;margin-top:14px}.note{border-left:4px solid #60a5fa;background:#17283e;padding:14px 18px;border-radius:7px}.warn{border-left-color:#f59e0b}.small{font-size:.88rem;color:#9cb2cb}a{color:#90c5ff}'''
body='<main><div class="small">D_VLA / 接触偏好学习 / 阶段 0–2 核查 · 北京时间 '+esc(stamp)+'</div><h1>真实表面来源与遮挡定位：跨场景案例</h1><p class="lead">这页展示的是阶段 2 的表面定位证据，不是最终评分模型的预测，更不是力学接触真值。每张图写明来源帧和能验证到的范围；遮挡后无法确认的位置保留未知。</p><div class="bar"><span class="pill">训练/验证：20/4 整段示范，互不交叉</span><span class="pill">状态对应：回放帧 t ↔ 官方 obs[t−1]</span><span class="pill">当前点云取自真实深度</span></div><div class="note"><b>读图方式</b>：夹取图左侧绿色是接触前可见的自动稳定表面候选，右侧橙色是后续真实深度来源。抽屉图橙色为先前真实表面，绿色为局部运动映射。开关图只画可观测来源，遮挡部分没有确认标记。颜色都不是网络打分。</div>'+''.join(cards)+'<div class="note warn"><b>本阶段验收边界</b>：夹取来源核对通过；抽屉只在第 70 帧得到有限的局部留出支持；开关遮挡面和双物体身份未通过。当前远程材料没有“推/关闭抽屉”的 RGB-D 回放，不能拿拉开抽屉倒放充当推的结果。后续需要另取该类示范，先走同样的时间、标定和身份核查。</div><p class="small">所有输入、图、审计与原示范保留在远程。阶段 3 接触证据及最终点云评分尚未运行。完整数值与验收结论见<a href="夹爪物体接触偏好学习_完整方案.md">同一份方案</a>。</p></main>'
out='<!doctype html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>阶段 0–2 表面定位核查</title><style>'+style+'</style></head><body>'+body+'</body></html>'
p=R/'docs/接触偏好_阶段012_案例核查.html';p.write_text(out,encoding='utf-8')
print({'page':str(p.relative_to(R)),'bytes':p.stat().st_size,'cards':len(cards),'image_links':out.count('<img')})
